void printEvenCountPerRow(const int a[][MAX], int R, int C) {
    for (int i = 0; i < R; ++i) {
        int count = 0;
        for (int j = 0; j < C; ++j)
            if (a[i][j] % 2 == 0) ++count;
        cout << count << '\n';
    }
}

